rsor:pointer}.icon-button:hover{border-color:var(--acid)}.game-layout{display:grid;grid-template-columns:190px minmax(0,1fr) 220px;gap:36px;padding:34px 0 30px;min-height:calc(100vh - 82px)}.rail{display:flex;flex-direction:column;justify-content:space-between;padding:15px 0 14px;border-right:1px solid #ffffff0a}.eyebrow{font:10px var(--mono);letter-spacing:.13em;color:var(--muted)}.eyebrow b{color:var(--acid);font-weight:500;margin-left:4px}.night-progress{width:125px;height:2px;background:#ffffff15;margin:15px 0 34px}.night-progress i{height:100%;display:block;width:34%;background:var(--acid);transition:width .4s}.phase-list{display:flex;flex-direction:column;gap:5px;padding-right:20px}.phase-item{display:flex;align-items:center;gap:13px;padding:12px 10px;color:#68696e;border-left:1px solid transparent;transition:.2s}.phase-item .phase-no{font:10px var(--mono);color:#55565b}.phase-item span:last-child{font:11px var(--mono);letter-spacing:.035em}.phase-item.active{color:var(--cream);border-left-color:var(--acid);background:linear-gradient(90deg,#d4fc6510,transparent)}.phase-item.active .phase-no{color:var(--acid)}.phase-item.done{color:#8f9b72}.phase-item.done .phase-no{color:#8f9b72}.rail-bottom{padding:0 14px}.server-status{display:flex;align-items:center;gap:10px;padding-bottom:24px;border-bottom:1px solid #ffffff12}.server-light{background:var(--acid);box-shadow:0 0 8px #d4fc6570;width:6px;height:6px}.server-status .eyebrow{font-size:9px}.server-status strong{display:block;font:10px var(--mono);letter-spacing:.1em;margin-top:5px;color:var(--acid)}.rail-note{font:9px var(--mono);letter-spacing:.12em;color:#73747a;line-height:1.75;margin-top:19px}.rail-note span{font-size:8px;color:#505157}.stage-wrap{display:flex;flex-direction:column;min-width:0}.stage-meta{display:flex;align-items:center;justify-content:space-between;margin:9px 0 16px}.stage-meta .eyebrow{color:#72747a}.mono{font:10px var(--mono);letter-spacing:.1em;color:#73747a}.stage{position:relative;flex: