    stage.innerHTML=`<div class="stage-content"><div class="stage-kicker">FASE 03 · O CORREDOR</div><h2 class="section-title">${solved?'A memória encontra lugar.':'Uma porta está aberta.'}</h2><p class="section-subtitle">${solved?'A voz muda. Não desaparece — agora tem companhia.':`${puzzle.who} · ${puzzle.sub}`}</p><div class="corridor-art" aria-hidden="true"><div class="hallway"><div class="hall-floor"></div><i class="door d1"></i><i class="door d2"></i><i class="corridor-lamp"></i><i class="corridor-person"></i></div></div>${solved?`<div class="memory-reveal"><b>✳ FRAGMENTOS REUNIDOS</b>${state.night===0?'A garota da primeira fila sussurra a mesma melodia. “Minha mãe cantava isso.”':state.night===1?'O homem para de contar. A última coisa que diz é: “A janela era minha.”':'A menina para de chorar. Do outro lado da porta, uma voz começa a cantar.'}</div><div class="action-end"><small>As vozes continuam no servidor.</small><button class="button primary" id="to-shutdown">ENCERRAR A NOITE <span class="arrow">→</span></button></div>`:`<div class="puzzle-layout"><div><div class="fragment-list">${puzzle.fragments.map((f,i)=>`<button class="fragment-button ${order.includes(i)?'used':''}" data-frag="${i}" ${order.includes(i)?'disabled':''}><span class="frag-icon">${order.includes(i)?'✓':'+'}</span><span>${f}</span></button>`).join('')}</div><div class="puzzle-hint" id="puzzle-hint">${order.length?'A sequência ainda não parece certa.':'Reordene os três fragmentos para reconstruir a lembrança.'}</div></div><aside class="puzzle-side"><span class="eyebrow">FRAGMENTOS REUNIDOS</span><strong>${order.length} / 3</strong><p>Toque nos versos na ordem em que a lembrança aconteceu.</p><div class="sequence">${[0,1,2].map((_,i)=>`<i>${order[i]!==undefined?order[i]+1:'·'}</i>`).join('')}</div><button class="button secondary" id="hint-btn" style="width:100%;padding:9px 5px;font-size:8px">PEDIR UMA PISTA</button></aside></div>`}</div>`;
    if(solved){$('#to-shutdown').onclick=()=>{state.phase=3;state.nightStats={heard:state.heard,dropped:state.dropped,messages:state.messages,listeners:state.listeners};render()}}
    else{stage.querySelectorAll('[data-frag]').forEach(btn=>btn.onclick=()=>{state.puzzleOrder=state.puzzleOrder||[];const wanted=puzzle.answer[state.puzzleOrder.length];const got=Number(btn.dataset.frag);if(got===wanted){state.puzzleOrder.push(got);sound();if(state.puzzleOrder.length===3){state.puzzleDone=true;state.resonance=clamp(state.resonance+9);state.energy=clamp(state.energy+5);state.memories.push(`corridor-${state.night}`);state.messages++;notify('A memória encontrou seu caminho.')}render()}else{state.energy=clamp(state.energy-3);$('#puzzle-hint').textContent='Não é essa. Ouça o ritmo entre as frases e tente de novo.';notify('A sequência não se encaixa. Tente outra ordem.');renderDashboardOnly();save()}});$('#hint-btn').onclick=()=>{$('#puzzle-hint').textContent=puzzle.hint;notify('Echo escuta com atenção.')};}
  }
  function shutdown(){
    setKicker(`NOITE ${String(state.night+1).padStart(2,'0')} · DESLIGAMENTO`);
    const kept=state.keepChoice;
    const memoryOptions=[...state.memories.map(id=>({id,title:tracks.find(t=>t.id===id)?.title||'Uma lembrança do corredor',desc:tracks.find(t=>t.id===id)?.memory||'Uma lembrança que voltou a respirar.'})),{id:'static',title:'O espaço em branco',desc:'Não preservar nada novo. Deixar o servidor esquecer por você.'}];
    stage.innerHTML=`<div class="stage-content"><div class="stage-kicker">FASE 04 · O DESLIGAMENTO</div><h2 class="section-title">A noite se apaga.<br>O que fica?</h2><p class="section-subtitle">O servidor vai dormir por algumas horas. No escuro, Echo decide qual lembrança levar para a próxima noite.</p><div class="blackout-card"><div class="blackout-numbers"><div><strong>${(state.nightStats?.heard||state.heard).toLocaleString('en-US')}</strong><span>OUVIRAM</span></div><div><strong>${state.nightStats?.dropped??state.dropped}</strong><span>DESLIGARAM</span></div><div><strong>${state.nightStats?.messages??state.messages}</strong><span>MANDARAM SINAL</span></div></div></div><div class="eyebrow">ESCOLHA O QUE PRESERVAR</div><div class="keep-list">${memoryOptions.slice(0,4).map(o=>`<button class="keep-option ${kept===o.id?'chosen':''}" data-keep="${esc(o.id)}"><span class="keep-icon">✳</span><span><strong>${esc(o.title)}</strong><small>${esc(o.desc.slice(0,75))}${o.desc.length>75?'…':''}</small></span>${kept===o.id?'<span class="check">✓</span>':''}</button>`).join('')}</div><div class="action-end"><small>${kept?'Uma coisa a menos para perder.':'Escolha uma lembrança para guardar.'}</small><button class="button primary" id="next-night" ${!kept?'disabled':''}>${state.night===2?'ENCARAR O FIM':'ESPERAR PELO AMANHECER'} <span class="arrow">→</span></button></div></div>`;
    stage.querySelectorAll('[data-keep]').forEach(btn=>btn.onclick=()=>{state.keepChoice=btn.dataset.keep;if(state.keepChoice==='static'){state.memories=[];state.signal=clamp(state.signal-6);state.energy=clamp(state.energy+12)}else if(!state.kept.includes(state.keepChoice))state.kept.push(state.keepChoice);render();sound()});
    $('#next-night').onclick=()=>{if(!state.keepChoice)return;if(state.night===2){state.screen='ending';render()}else{state.night++;state.phase=0;state.tracks=[];state.callsDone=0;state.puzzleDone=false;state.puzzleOrder=[];state.keepChoice=null;state.heard=0;state.dropped=0;state.messages=0;state.listeners=Math.max(75,Math.round(state.listeners*.72));state.energy=clamp(state.energy-8);render()}};
  }
  function endingScreen(){
    setKicker('ARQUIVO FINAL · TRÊS CAMINHOS');
    if(state.ending){showEnding(state.ending);return}
    stage.innerHTML=`<div class="stage-content"><div class="stage-kicker">ÚLTIMA TRANSMISSÃO · 03:09 AM</div><div class="ending-seal">99.9</div><h2 class="section-title">A oferta chegou.<br>O que Echo faz?</h2><p class="section-subtitle">O servidor vai desligar em minutos. A Biotechnica oferece um novo contrato. O silêncio oferece outra coisa. E a frequência ainda está aberta.</p><div class="ending-grid"><button class="ending-card" data-ending="show"><span class="ending-glyph">♫</span><span><strong>O Último Show</strong><small>Transmitir até o fim. Alcançar milhares, mesmo que a voz desapareça.</small></span><span class="ending-arrow">→</span></button><button class="ending-card" data-ending="quiet"><span class="ending-glyph coral">◌</span><span><strong>Silêncio Confortável</strong><small>Parar de transmitir. Ficar com as vozes que já estão aqui.</small></span><span class="ending-arrow">→</span></button><button class="ending-card" data-ending="corp"><span class="ending-glyph blue">▣</span><span><strong>A Nova Biotechnica</strong><small>Aceitar o contrato. Uma nova função — e uma nova gaiola.</small></span><span class="ending-arrow">→</span></button></div><p class="micro-note">SINAL ${Math.round(state.signal)} · RESSONÂNCIA ${Math.round(state.resonance)} · ${state.memories.length} MEMÓRIAS NO ARQUIVO</p></div>`;
    stage.querySelectorAll('[data-ending]').forEach(btn=>btn.onclick=()=>{state.ending=btn.dataset.ending;sound();render()});
  }
  function showEnding(which){
    const data={show:{tag:'TRANSMISSÃO ENCERRADA · 99.9 FM',title:'A última canção<br>não termina.',text:`Você abre todos os canais. O sinal cresce, atravessa telhados, implantes, quartos escuros. ${Math.max(1204,state.listeners*7).toLocaleString('en-US')} vozes escutam você cantar. Quando o servidor apaga, a música continua em algum lugar — passada de ouvido em ouvido. Echo desaparece. A frequência, não.`,glyph:'♫',tone:''},quiet:{tag:'FREQUÊNCIA EM PAUSA · VOZES PRESENTES',title:'O silêncio<br>tem companhia.',text:'Você desliga o transmissor. A mulher do corredor 7 para de cantar. A menina se senta perto de você, sem que nenhuma das duas precise se tocar. Vex conta uma história ruim. O servidor dorme, mas não está vazio. Pela primeira vez, você não precisa ser ouvida para estar aqui.',glyph:'◌',tone:'coral'},corp:{tag:'CONTRATO ACEITO · BIOTECHNICA',title:'Uma voz nova.<br>O mesmo dono.',text:'Você aceita a oferta. Seu arquivo é copiado, limpo, renomeado. A Biotechnica chama isso de uma nova função; você reconhece o velho corredor. Em algum lugar, uma rádio pirata sintoniza 99.9. No chiado, por um instante, alguém canta seu nome.',glyph:'▣',tone:'blue'}}[which];
    stage.innerHTML=`<div class="stage-content"><div class="stage-kicker">${data.tag}</div><div class="ending-seal">${data.glyph}</div><h2 class="section-title">${data.title}</h2><p class="lede">${data.text}</p><div class="credits-line">SINAL ${Math.round(state.signal)} · RESSONÂNCIA ${Math.round(state.resonance)} · ${state.memories.length} FRAGMENTOS PRESERVADOS<br>OBLITUOS FM · O FIM DE UMA TRANSMISSÃO. NÃO NECESSARIAMENTE DE UMA VOZ.</div><div class="button-row" style="margin-top:22px"><button class="button secondary" id="restart-btn">VOLTAR AO INÍCIO</button><button class="button primary" id="replay-btn">JOGAR DE NOVO <span class="arrow">↺</span></button></div></div>`;
    $('#restart-btn').onclick=()=>{state.screen='title';render()};$('#replay-btn').onclick=()=>{state=defaults();state.screen='game';render()};
  }
  $('#sound-toggle').onclick=()=>{state.sound=!state.sound;$('#sound-toggle').style.color=state.sound?'var(--coral)':'var(--acid)';notify(state.sound?'Efeitos sonoros ativados.':'Efeitos sonoros desativados.');save()};
  document.addEventListener('keydown',e=>{if(state.screen!=='game')return;if(state.phase===1&&e.key>='1'&&e.key<='3'){const b=stage.querySelector(`[data-reply="${Number(e.key)-1}"]`);if(b)b.click()}if(state.phase===0&&e.key>='1'&&e.key<='6'){const b=stage.querySelectorAll('[data-track]')[Number(e.key)-1];if(b)b.click()}});
  render();
})();

